<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue';
import QRCode from 'qrcode';
import { api } from '../api';
import { useGameStore } from '../stores/game';
import PlayerRoster from './PlayerRoster.vue';
const game = useGameStore(); const address = ref(''); const qr = ref(''); const networkError = ref(''); const copied = ref(false);
const state = computed(() => game.publicState!);
const joinUrl = computed(() => { try { const url = new URL('/join', address.value); if(!['http:','https:'].includes(url.protocol)) return ''; url.searchParams.set('code',state.value.code); return url.toString(); } catch { return ''; } });
const readyToStart = computed(() => state.value.players.length >= state.value.scenario.minPlayers && state.value.players.every(p => p.ready && p.connected));
const localAddress = computed(() => { try { return ['localhost','127.0.0.1','[::1]'].includes(new URL(address.value).hostname); } catch { return false; } });
onMounted(async () => { if (!game.isHost) return; try { const network = await api<{urls:string[]}>('/api/network'); const isLocal = ['localhost','127.0.0.1','[::1]'].includes(location.hostname); address.value = !isLocal ? location.origin : network.urls[0] || ''; if(!address.value) networkError.value = '没有检测到局域网地址。请连接 Wi-Fi 后填写电脑的局域网访问地址。'; } catch (e) { networkError.value = e instanceof Error ? e.message : '读取网络地址失败'; if (!['localhost','127.0.0.1'].includes(location.hostname)) address.value = location.origin; } });
watch(joinUrl, async value => { if (!value) { qr.value=''; return; } try { const image = await QRCode.toDataURL(value,{width:256,margin:2,color:{dark:'#151817',light:'#edece6'}}); if(joinUrl.value===value) qr.value=image; } catch { qr.value=''; } }, {immediate:true});
async function copy() { if (!joinUrl.value) return; try { await navigator.clipboard.writeText(joinUrl.value); copied.value=true; setTimeout(()=>copied.value=false,2000); } catch { networkError.value='当前浏览器不支持复制，请长按或手动复制下方链接。'; } }
</script>
<template><section class="lobby-layout"><div class="lobby-main"><div class="eyebrow">WAITING ROOM / 入住之前</div><h1>{{ state.scenario.title }}</h1><p class="lobby-synopsis">{{ state.scenario.synopsis }}</p><div class="room-code-block"><span>房间码</span><strong>{{ state.code }}</strong><span>{{ state.scenario.minPlayers }}—{{ state.scenario.maxPlayers }} 人 · {{ state.scenario.estimatedMinutes.replace(/分钟$/, '') }}</span></div><div class="panel lobby-players"><div class="panel-heading"><h2>登记旅客</h2><span>{{ state.players.length }} / {{ state.scenario.maxPlayers }}</span></div><PlayerRoster :players="state.players" lobby :my-id="game.session?.playerId" /></div><div v-if="game.isHost" class="lobby-control"><button class="button primary" :disabled="!readyToStart || game.status!=='connected'" @click="game.send('start')">开始游戏 →</button><p class="muted small">{{ state.players.length < state.scenario.minPlayers ? `至少需要 ${state.scenario.minPlayers} 位旅客。` : !readyToStart ? '等待所有旅客在线并准备。' : '所有人已准备，普通访客的故事即将开始。' }}</p></div><div v-else class="lobby-control player-ready"><button class="button" :class="game.me?.ready ? 'secondary' : 'primary'" :disabled="game.status!=='connected'" @click="game.send('ready', !game.me?.ready)">{{ game.me?.ready ? '已准备 ✓ · 取消准备' : '我已准备 →' }}</button><p class="muted small">{{ game.me?.ready ? '等待主持人开始。请保持此标签页打开。' : '准备好面对旅馆，留意之后的私人消息。' }}</p></div></div><aside v-if="game.isHost" class="lobby-invite panel"><div class="eyebrow">INVITE YOUR VISITORS</div><h2>让朋友扫码入住</h2><div class="qr-container"><img v-if="qr" :src="qr" alt="扫码加入当前房间" /><div v-else class="qr-placeholder">等待有效的局域网地址</div></div><p class="muted small">所有设备连接同一个 Wi-Fi。<br>手机无需安装应用。</p><label class="field-label" for="lan-address">电脑的局域网地址 <span>可修改</span></label><input id="lan-address" v-model="address" type="url" placeholder="http://192.168.1.10:5173" /><p v-if="networkError || localAddress" class="inline-error small">{{ localAddress ? 'localhost 只适用于这台电脑，请使用局域网 IP。' : networkError }}</p><a v-if="joinUrl" class="join-url" :href="joinUrl" target="_blank" rel="noopener">{{ joinUrl }}</a><button class="button secondary full" :disabled="!joinUrl" @click="copy">{{ copied ? '链接已复制 ✓' : '复制邀请链接' }}</button></aside><aside v-else class="panel visitor-notice"><div class="eyebrow">请在开始前阅读</div><h2>你的手机是一份秘密档案</h2><ol><li>所有人以普通访客开局，私人指令随故事出现。</li><li>允许现实交流、合作与隐瞒。</li><li>每轮独立提交一次行动，提交后不可撤回。</li><li>没有倒计时，全员选完结算，全员已读继续。</li></ol><p class="muted small">主持电脑只展示公开信息，无法查看你的秘密行动。</p></aside></section></template>
